from ta_moler.device.generic_rtg_cus import GenericRtgCus


class RTG(GenericRtgCus):
    r"""
    Rtg device class.

    Example of device in yaml configuration file:
    - without PROXY_PC:
      RTG:
        DEVICE_CLASS: ta_moler.device.rtg.RTG
        CONNECTION_HOPS:
          UNIX_LOCAL:
            WS:
              execute_command: ssh # default value
              command_params:
                expected_prompt: 'remote#'
                host: remote_host
                login: remote_login
                password: login
                set_timeout: False
          WS:
            WS_ROOT:
                password: root_password
                expected_prompt: r'root_password#'
          RTG:
            WS:
              command_params:
                expected_prompt: 'remote#'
          WS_ROOT:
            WS:
              command_params:
                expected_prompt: 'remote#'
          SCHMMI:
            WS:
              command_params:
                expected_prompt: 'remote#'

    - with PROXY_PC:
      RTG_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.rtg.RTG
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
                set_timeout: False
          PROXY_PC:
            WS:
              execute_command: ssh # default value
              command_params:
                expected_prompt: 'remote#'
                host: remote_host
                login: remote_login
                password: login
                set_timeout: False
          WS:
            WS_ROOT:
                password: root_password
                expected_prompt: r'root_password#'
          WS:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc#
          RTG:
            WS:
              command_params:
                expected_prompt: 'remote#'
          WS_ROOT:
            WS:
              command_params:
                expected_prompt: 'remote#'
          SCHMMI:
            WS:
              command_params:
                expected_prompt: 'remote#'
    """

    ue_sim = "RTG"

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(RTG, self)._get_packages_for_state(state, observer)

        if not available:
            if state == self.ws or state == self.ws_root:
                available = {self.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.rtg.ws'],
                             self.events: ['moler.events.shared', 'moler.events.unix']}
            if available:
                return available[observer]

        return available
